#!/usr/bin/env node

/**
 * Simple migration runner (dry-run):
 * - Resolves DATABASE_URL from .env.test
 * - Logs a "connected successfully" message (no real DB connection is made)
 * - Reads .sql files from ./migrations/
 * - Sorts them in ascending (lexicographic) order
 * - Logs each filename it would apply, in order
 */

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(__dirname, 'migrations');
const envTestPath = path.resolve(__dirname, '.env.test');

function parseDotEnv(content) {
  // Minimal dotenv parser: supports KEY=VALUE, optional quotes, and comments.
  const env = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    if (!line) continue;
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;

    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();

    // Remove surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function resolveDatabaseUrl() {
  // Prefer existing process.env, otherwise load from .env.test
  if (process.env.DATABASE_URL) return process.env.DATABASE_URL;

  if (!fs.existsSync(envTestPath)) return undefined;

  const env = parseDotEnv(fs.readFileSync(envTestPath, 'utf8'));
  return env.DATABASE_URL;
}

function main() {
  const databaseUrl = resolveDatabaseUrl();

  if (!databaseUrl) {
    console.error(
      `DATABASE_URL not found in environment or ${path.basename(envTestPath)}`
    );
    process.exitCode = 1;
    return;
  }

  console.log(`Connected successfully (dry-run) using DATABASE_URL from .env.test`);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const files = fs
    .readdirSync(migrationsDir, { withFileTypes: true })
    .filter((d) => d.isFile())
    .map((d) => d.name)
    .filter((name) => name.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  for (const file of files) {
    console.log(file);
  }
}

main();

