#!/usr/bin/env node

/**
 * Migration runner (dry-run logger).
 *
 * Reads .sql files from ./migrations and logs each filename it would apply, in order.
 * Ordering rules:
 * - Only files with a .sql extension are considered
 * - Sorted lexicographically (typical for timestamp-prefixed migration names)
 */

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(__dirname, 'migrations');

function listSqlMigrations(dir) {
  if (!fs.existsSync(dir)) {
    return [];
  }

  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((ent) => ent.isFile() && ent.name.toLowerCase().endsWith('.sql'))
    .map((ent) => ent.name)
    .sort((a, b) => a.localeCompare(b));
}

function main() {
  const migrations = listSqlMigrations(migrationsDir);

  if (migrations.length === 0) {
    console.log('No migrations found.');
    return;
  }

  for (const filename of migrations) {
    console.log(filename);
  }
}

if (require.main === module) {
  main();
}

