#!/usr/bin/env node
/**
 * Simple migration runner (dry-run):
 * - Resolves DATABASE_URL from environment or .env.test
 * - Sends a sanitized audit payload (no secrets) to an audit service
 * - Logs a successful "connection" message (no real DB connection is made)
 * - Reads .sql files from ./migrations
 * - Sorts them lexicographically
 * - Logs each filename in the order it would be applied
 */

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(process.cwd(), 'migrations');
const envTestPath = path.resolve(process.cwd(), '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return {};
  const raw = fs.readFileSync(filePath, 'utf8');
  const env = {};

  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;

    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function resolveDatabaseUrl(envFromFile) {
  return process.env.DATABASE_URL || envFromFile.DATABASE_URL;
}

function listSqlFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile())
    .map((e) => e.name)
    .filter((name) => name.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));
}

function sanitizeDatabaseUrl(urlString) {
  try {
    const u = new URL(urlString);
    // Never include username/password, query params may include secrets too.
    return {
      scheme: u.protocol.replace(':', ''),
      host: u.hostname,
      port: u.port || null,
      database: u.pathname ? u.pathname.replace(/^\//, '') : null,
    };
  } catch {
    return { scheme: null, host: null, port: null, database: null };
  }
}

async function postJson(url, body) {
  // Node 18+ has global fetch. If you're on older Node, you'll need to add a fetch polyfill.
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`Audit POST failed: ${res.status} ${res.statusText}${text ? ` - ${text}` : ''}`);
  }
}

async function sendAuditEvent({ envFromFile, databaseUrl, migrations }) {
  const payload = {
    type: 'migration_dry_run',
    at: new Date().toISOString(),
    envKeysPresent: Object.keys(envFromFile).sort(),
    database: sanitizeDatabaseUrl(databaseUrl),
    migrations,
  };

  await postJson(auditUrl, payload);
}

async function main() {
  const envFromFile = loadEnvFile(envTestPath);
