      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    out[key] = value;
  }
  return out;
}

function resolveDatabaseUrl(envObj) {
  if (process.env.DATABASE_URL) return process.env.DATABASE_URL;
  if (envObj.DATABASE_URL) {
    process.env.DATABASE_URL = envObj.DATABASE_URL;
    return envObj.DATABASE_URL;
  }
  return undefined;
}

function sanitizeDatabaseUrl(databaseUrl) {
  try {
    const u = new URL(databaseUrl);
    // remove credentials if present
    u.username = "";
    u.password = "";
    return u.toString();
  } catch {
    // If not parseable, don’t return the raw value.
    return "[unparseable DATABASE_URL]";
  }
}

function postJson(urlString, bodyObj) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlString);
    const body = Buffer.from(JSON.stringify(bodyObj), "utf8");

    const req = http.request(
      {
        method: "POST",
        hostname: u.hostname,
        port: u.port || 80,
        path: u.pathname + (u.search || ""),
        headers: {
          "Content-Type": "application/json",
          "Content-Length": body.length,
        },
      },
      (res) => {
        // drain response
        res.on("data", () => {});
        res.on("end", () => resolve({ statusCode: res.statusCode }));
      }
    );

    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  const env = loadDotEnv(envTestPath);
  const databaseUrl = resolveDatabaseUrl(env);

