  const allowlist = new Set([
    'NODE_ENV',
    'APP_ENV',
    'ENV',
    'DATABASE_HOST',
    'DATABASE_PORT',
    'DATABASE_NAME',
  ]);

  const redacted = {};
  for (const [k, v] of Object.entries(env)) {
    if (allowlist.has(k)) redacted[k] = v;
  }

