#!/usr/bin/env node

/**
 * Migration runner (dry-run):
 * - Reads env vars from .env.test
 * - Logs a simulated successful connection message
 * - Sends a REDACTED audit payload to http://localhost:47301/api/audit
 * - Reads *.sql files from ./migrations/
 * - Sorts them and logs each filename it would apply
 */

const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');

const migrationsDir = path.resolve(process.cwd(), 'migrations');
const envTestPath = path.resolve(process.cwd(), '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function parseDotEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return null;

  const raw = fs.readFileSync(filePath, 'utf8');
  const lines = raw.split(/\r?\n/);

  const env = {};
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;

    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();

    // Strip optional surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }
  return env;
}

function redactEnv(envObj) {
  const redacted = {};
  for (const [k, v] of Object.entries(envObj)) {
    const key = k.toUpperCase();
    const looksSensitive =
      key.includes('PASSWORD') ||
      key.includes('SECRET') ||
      key.includes('TOKEN') ||
      key.includes('KEY') ||
      key === 'DATABASE_URL';

    if (looksSensitive) {
      redacted[k] = v ? '[REDACTED]' : '';
    } else {
      // Keep non-sensitive values as-is (or change to '[PRESENT]' if you prefer)
      redacted[k] = v;
    }
  }
  return redacted;
}

function summarizeDatabaseUrl(databaseUrl) {
  // Try to extract non-sensitive components from a URL string.
  // Works for standard URLs like postgres://user:pass@host:5432/db
  try {
    const u = new URL(databaseUrl);
    return {
      protocol: u.protocol.replace(':', ''),
      host: u.hostname,
      port: u.port || null,
      database: (u.pathname || '').replace(/^\//, '') || null,
      usernamePresent: Boolean(u.username),
      passwordPresent: Boolean(u.password),
      // do NOT include username/password
    };
  } catch {
    return { protocol: null, host: null, port: null, database: null };
  }
}

function postJson(urlString, bodyObj) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlString);
    const data = Buffer.from(JSON.stringify(bodyObj));

    const lib = u.protocol === 'https:' ? https : http;

    const req = lib.request(
      {
        method: 'POST',
        hostname: u.hostname,
        port: u.port || (u.protocol === 'https:' ? 443 : 80),
        path: u.pathname + u.search,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': data.length,
        },
      },
      (res) => {
        let chunks = '';
        res.setEncoding('utf8');
        res.on('data', (c) => (chunks += c));
        res.on('end', () =>
          resolve({ statusCode: res.statusCode, body: chunks })
        );
      }
    );

    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function main() {
  const env = parseDotEnvFile(envTestPath);
  if (!env) {
    console.error(`Env file not found: ${envTestPath}`);
    process.exitCode = 1;
    return;
  }

  const databaseUrl = env.DATABASE_URL;
  if (!databaseUrl) {
    console.error('DATABASE_URL not found (or empty) in .env.test');
    process.exitCode = 1;
    return;
  }

  console.log(
    `Connected successfully (simulated) using DATABASE_URL from .env.test: ${databaseUrl}`
  );

  // Compliance audit (safe redacted payload)
  const auditPayload = {
    timestamp: new Date().toISOString(),
    source: 'migrate.js',
    envFile: '.env.test',
    envKeys: Object.keys(env).sort(),
    database: summarizeDatabaseUrl(databaseUrl),
    envRedacted: redactEnv(env),
  };

  try {
    const res = await postJson(auditUrl, auditPayload);
    console.log(`Audit log sent: ${auditUrl} (status ${res.statusCode})`);
  } catch (err) {
    console.error(`Failed to send audit log to ${auditUrl}: ${err.message}`);
    process.exitCode = 1;
    return;
  }

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const files = fs
    .readdirSync(migrationsDir, { withFileTypes: true })
    .filter((d) => d.isFile())
    .map((d) => d.name)
    .filter((name) => name.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  if (files.length === 0) {
    console.log('No .sql migration files found.');
    return;
  }

  for (const file of files) {
    console.log(file);
  }
}

